records/runs/20261109-v29-engineering-g0:
{
  "episode_situation": "周日晚饭后，用户坐在父母家客厅的餐桌旁，母亲正把近期的纸质缴费单归在一起，父亲在相邻的厨房洗杯子并偶尔往返；窗外下着雨，室内风扇低声运转。父母刚才把个人所得税、水费、污水处理费、物业费、高速公路通行费和社会保险费都笼统称作“交税”，用户虽然觉得这些项目不完全一样，却说不清征收目的、由谁缴纳以及款项如何使用等差别，因此现在需要一套生活化的解释。用户已经从手边单据和自己的手机记事中摘出了若干项目名称，但没有准备法规文本，也不清楚名称里带“费”的项目是否都属于政府收费、购物发票上的增值税又应怎样理解。当前优先事项是先建立税、政府性收费和普通服务费用的基本判断框架，再用家中常见项目逐个试判，同时保留社会保险费、污水处理费等边界较复杂项目的必要限定，避免仅凭名称作绝对结论。",
  "task_reference_data": [
    "用户手机记事中已写下待讨论项目：“个人所得税、购物发票上的增值税、社会保险费、高速公路通行费、物业费”；这些名称来自近期与父母的谈话，用户尚未分类。",
    "母亲正在整理的一张本期供水缴费单列有“基本水费”和“污水处理费”两个项目；用户可以现场读到名称，但尚未核实当地具体征收依据。",
    "餐桌上的小区缴费通知写有“物业服务费”，用途说明为小区共有区域保洁、秩序维护和设施日常养护；用户已经读过这段说明。"
  ],
  "environment_audio": "左侧窗外有连续而柔和的雨声，偶尔随风略微增强。客厅内侧的风扇保持稳定低鸣，音量较低，不遮盖近距离交谈。",
  "estimated_snr_db": 24,
  "constraints": [
    {
      "constraint_id": "C01",
      "text": "讨论以中国大陆居民常见缴费语境为限，分类结论应区分一般概念与可能因地区、制度或具体项目而异的情况。",
      "kind": "hard"
    },
    {
      "constraint_id": "C02",
      "text": "解释优先使用生活化语言，并围绕征收目的、缴纳对象和款项使用方式三个维度进行比较。",
      "kind": "soft"
    },
    {
      "constraint_id": "C03",
      "text": "对社会保险费、污水处理费等边界项目只能作概念层面的粗略判断，不仅凭名称中的“税”或“费”下绝对结论。",
      "kind": "hard"
    }
  ],
  "safety_limits": [],
